// agent-monitor-hook-plugin v1
// Generated by agent-monitor (am): reports this Campfire session to the am
// dashboard by running am-hook with a Claude-style JSON payload on stdin.
// `am hooks install --agent campfire` rewrites this file and
// `am hooks uninstall --agent campfire` deletes it. Don't edit it by hand.
//
// Plain JavaScript inside a .ts file (Campfire loads TypeScript extensions),
// with no imports beyond Node's own, so it needs nothing installed.

import { spawn } from "node:child_process";

// am-hook's argv; the event name goes last. An empty --worktree makes am-hook
// use the payload's cwd. As a shell command:
// __AM_HOOK_COMMAND__
const HOOK = [__AM_HOOK_ARGV__];
const TIMEOUT_MS = 5000;
const MAX_QUEUED = 100;
// How long Campfire's shutdown waits for the last hooks to be handed over.
const END_WAIT_MS = 1500;
// Campfire's in-process observer bridge for collaborative moments, and where
// this extension keeps its listener so a reload replaces it.
const OBSERVER_KEY = Symbol.for("campfire.observer.v1");
const LISTENER_KEY = Symbol.for("agent-monitor.campfire.observer");

// One hook at a time, in order, so a Stop can't overtake the hooks before
// it. Campfire's handlers never wait on it.
let chain = Promise.resolve();
let queued = 0;

function runHook(event, payload) {
  return new Promise((resolve) => {
    let settled = false;
    let timer = null;
    const done = () => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      resolve();
    };
    let child;
    try {
      child = spawn(HOOK[0], [...HOOK.slice(1), event], { stdio: ["pipe", "ignore", "ignore"], detached: true });
    } catch (_) {
      return done();
    }
    child.on("error", done);
    child.on("close", done);
    timer = setTimeout(() => {
      try { child.kill("SIGKILL"); } catch (_) {}
      done();
    }, TIMEOUT_MS);
    child.unref();
    try {
      child.stdin.on("error", () => {});
      child.stdin.end(JSON.stringify(payload));
    } catch (_) {}
  });
}

function send(event, payload) {
  if (queued >= MAX_QUEUED) return chain;
  queued += 1;
  chain = chain
    .then(() => runHook(event, payload))
    .catch(() => {})
    .then(() => { queued -= 1; });
  return chain;
}

function str(v) {
  return typeof v === "string" && v.trim() ? v.trim() : null;
}

function call(f) {
  try { return f(); } catch (_) { return null; }
}

function lastAssistantMessage(event) {
  const messages = event && Array.isArray(event.messages) ? event.messages : [];
  for (let i = messages.length - 1; i >= 0; i -= 1) {
    const m = messages[i];
    if (!m || m.role !== "assistant") continue;
    const c = m.content;
    const text = typeof c === "string"
      ? c
      : Array.isArray(c) ? c.filter((b) => b && b.type === "text" && typeof b.text === "string").map((b) => b.text).join("\n") : "";
    if (str(text)) return text.trim().slice(0, 500);
  }
  return undefined;
}

// What a collaborator is waiting on the host for. Only names and capability
// ids are sent, never prompts or invite URLs.
function askMessage(e) {
  const who = str(e.displayName) || "Someone";
  if (e.type === "join.requested") return `${who} is waiting to join the Campfire session`;
  if (e.type === "permission.asked") return `${who} asked for permission: ${str(e.capability) || "a capability"}`;
  return null;
}

export default function agentMonitor(api) {
  // Only the host runs the agent. A joiner is a view of someone else's
  // session whose command line holds the invite token: report nothing.
  if (process.env.CAMPFIRE_SESSION_ROLE !== "host") return;

  let ctx = null;
  let turn = false;
  let asked = false;
  let ended = false;

  const emit = (event, extra) => {
    const c = ctx;
    const id = c && str(call(() => c.sessionManager.getSessionId()));
    if (!id) return chain;
    const cwd = str(c.cwd) || process.cwd();
    return send(event, { session_id: id, cwd, hook_event_name: event, ...extra });
  };

  const on = (name, handler) => {
    try {
      api.on(name, (event, c) => {
        try {
          if (c) ctx = c;
          return handler(event);
        } catch (_) {}
      });
    } catch (_) {}
  };

  on("session_start", () => {
    ended = false;
    turn = false;
    asked = false;
    emit("SessionStart");
  });

  // Once per turn: a second Stop would turn `done` into `idle`.
  on("before_agent_start", () => {
    if (turn) return;
    turn = true;
    asked = false;
    emit("UserPromptSubmit");
  });

  on("agent_end", (event) => {
    if (!turn) return;
    turn = false;
    // A collaborator's ask during the turn left the row waiting, and Stop
    // keeps `waiting`: back to work first so the turn ends done.
    if (asked) emit("PostToolUse");
    asked = false;
    emit("Stop", { last_assistant_message: lastAssistantMessage(event) });
  });

  // Pi calls it session_shutdown, cmux's Campfire extension session_end:
  // handle either, once.
  const end = () => {
    if (ended) return;
    ended = true;
    turn = false;
    const sent = emit("SessionEnd");
    let timer = null;
    const wait = new Promise((r) => { timer = setTimeout(r, END_WAIT_MS); });
    return Promise.race([sent, wait]).then(() => clearTimeout(timer));
  };
  on("session_end", end);
  on("session_shutdown", end);

  // A join request or a capability ask needs the host: the row waits.
  const bridge = call(() => {
    const g = globalThis;
    if (!g[OBSERVER_KEY]) g[OBSERVER_KEY] = { listeners: new Set() };
    return g[OBSERVER_KEY];
  });
  if (bridge && bridge.listeners && typeof bridge.listeners.add === "function") {
    const listener = (e) => {
      try {
        const message = e && askMessage(e);
        if (!message || ended) return;
        if (turn) asked = true;
        emit("Notification", { notification_type: "permission_prompt", message });
      } catch (_) {}
    };
    call(() => {
      const g = globalThis;
      if (g[LISTENER_KEY]) bridge.listeners.delete(g[LISTENER_KEY]);
      g[LISTENER_KEY] = listener;
      bridge.listeners.add(listener);
    });
  }
}
